void vhost_scsi_send_event(struct vhost_scsi *vs, struct vhost_scsi_tpg *tpg,
                           struct se_lun *lun, u32 event, u32 reason)
{
    struct vhost_scsi_event *ve;
    struct se_node_acl *se_acl;
    struct se_portal_group *se_tpg;

    ve = kzalloc(sizeof(*ve), GFP_KERNEL);
    if (!ve)
        return;

    ve->ve_hdr.ve_type = VHOST_SCSI_EVENT;
    ve->ve_hdr.ve_index = vs->vs_index;
    ve->ve_hdr.ve_event = event;
    ve->ve_hdr.ve_reason = reason;

    if (tpg)
        ve->ve_tpg = *tpg;

    if (lun)
        ve->ve_lun = *lun;

    INIT_LIST_HEAD(&ve->ve_list);
    list_add_tail(&ve->ve_list, &vs->vs_event_list);

    queue_work(vs->vs_event_wq, &vs->vs_event_work);
}

void send_scsi_event(struct vhost_scsi *vs, struct vhost_scsi_tpg *tpg,
                     struct se_lun *lun, u32 event, u32 reason)
{
    struct scsi_event *e;

    e = kzalloc(sizeof(*e), GFP_KERNEL);
    if (!e)
        return;

    e->vs = vs;
    if (tpg) {
        e->tpg = tpg;
        e->tpg_id = tpg->tpg_id;
    }
    if (lun) {
        e->lun = lun;
        e->lun_id = lun->lun_id;
    }
    e->event = event;
    e->reason = reason;

    spin_lock(&vs->event_lock);
    list_add_tail(&e->list, &vs->event_list);
    spin_unlock(&vs->event_lock);

    queue_work(vs->event_wq, &vs->event_work);
}

